SELECT ?zone ?label ?point ?point_type ?ts_id WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_top_ZN_3") || CONTAINS(?label, "Perimeter_mid_ZN_3"))
  ?point brick:isPointOf ?zone .
  ?point a ?point_type .
  OPTIONAL { ?point ref:hasExternalReference ?ts_id . }
}

SELECT ?zone ?sensor ?ts_id WHERE {
  VALUES ?zone { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> }
  ?sensor brick:isPointOf ?zone .
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor ref:hasExternalReference ?ts_id .
}

SELECT ?zone ?point ?type ?ts_id WHERE {
  VALUES ?zone { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> }
  ?point brick:isPointOf ?zone .
  ?point a ?type .
  OPTIONAL { ?point ref:hasExternalReference ?ts_id . }
}

